{"content":"package cli

import (
	"errors"
	"reflect"
	"testing"
)

func check(t *testing.T, args []string, want Config) {
	t.Helper()
	got, err := Parse(args)
	if err != nil {
		t.Fatalf("Parse(%q) error: %v", args, err)
	}
	if got != (want) {
		t.Fatalf("Parse(%q) = %+v, want %+v", args, got, want)
	}
}

func expectErr(t *testing.T, args []string) {
	t.Helper()
	_, err := Parse(args)
	if err == nil || !errors.Is(err, ErrUsage) {
		t.Fatalf("Parse(%q) err = %v, want ErrUsage", args, err)
	}
}

func TestRules(t *testing.T) {
	check(t, []string{"-v"}, Config{Verbose: true, Count: 1, Output: "-"})
	check(t, []string{"-v", "-v"}, Config{Verbose: true, Count: 1, Output: "-"})
	check(t, []string{"-vv"}, Config{Verbose: true, Count: 1, Output: "-"})
	check(t, []string{"-n", "3"}, Config{Count: 3, Output: "-"})
	check(t, []string{"-n=4"}, Config{Count: 4, Output: "-"})
	check(t, []string{"--count", "5"}, Config{Count: 5, Output: "-"})
	check(t, []string{"--count=0"}, Config{Count: 0, Output: "-"})
	check(t, []string{"-n", "-5"}, Config{Count: -5, Output: "-"})
	check(t, []string{"-o", "f.txt"}, Config{Count: 1, Output: "f.txt"})
	check(t, []string{"-o=dir"}, Config{Count: 1, Output: "dir"})
	check(t, []string{"--output", "x"}, Config{Count: 1, Output: "x"})
	check(t, []string{"--tag=a", "--tag", "b"}, Config{Count: 1, Output: "-", Tags: []string{"a", "b"}})
	check(t, []string{"one", "two"}, Config{Count: 1, Output: "-", Args: []string{"one", "two"}})
	check(t, []string{"-", "one"}, Config{Count: 1, Output: "-", Args: []string{"-", "one"}})
	check(t, []string{"--", "-v"}, Config{Count: 1, Output: "-", Args: []string{"-v"}})
	check(t, []string{"pos1", "-v", "pos2"}, Config{Verbose: true, Count: 1, Output: "-", Args: []string{"pos1", "pos2"}})
	check(t, []string{"-n2"}, Config{Count: 2, Output: "-"})
	check(t, []string{"-vo"}, Config{Verbose: true, Count: 1, Output: "-"}) // -o takes next arg

	expectErr(t, []string{"-n"})
	expectErr(t, []string{"-n", "x"})
	expectErr(t, []string{"--count", "-1"})
	expectErr(t, []string{"-o"})
	expectErr(t, []string{"--tag"})
	expectErr(t, []string{"-x"})
	expectErr(t, []string{"--nope"})
}

func TestErrMentionsFlag(t *testing.T) {
	_, err := Parse([]string{"-n", "abc"})
	if err == nil || !errors.Is(err, ErrUsage) || !reflect.DeepEqual(true, contains(err.Error(), "-n")) {
		t.Fatalf("err = %v", err)
	}
}

func contains(s, sub string) bool {
	for i := 0; i+len(sub) <= len(s); i++ {
		if s[i:i+len(sub)] == sub {
			return true
		}
	}
	return false
}
